 using Microsoft.EntityFrameworkCore;
 using Microsoft.EntityFrameworkCore.Diagnostics;

 class BlogContext : DbContext
 {
     public DbSet<Blog> Blogs => Set<Blog>();

     protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
     {
         // Breaking change: EF Core 9 Cosmos provider no longer supports
         // synchronous I/O by default. Prefer async APIs; this opt-in
         // unblocks existing sync call-sites during migration.
         optionsBuilder.ConfigureWarnings(w =>
             w.Ignore(CosmosEventId.SyncNotSupported));
     }

     protected override void OnModelCreating(ModelBuilder modelBuilder)
     {
         // Breaking change 1: Default discriminator property renamed
         // from "Discriminator" to "$type". Existing documents still
         // store "Discriminator", so keep the old name.
         modelBuilder.Entity<Blog>(b =>
         {
             b.HasDiscriminator<string>("Discriminator");

             // Breaking change 2: Default id format changed from
             // "EntityType|Key" to just "Key". Existing documents
             // use the old format, so preserve it.
             b.HasPartitionKey(e => e.Id);
             b.Property(e => e.Id)
              .ToJsonProperty("id")
              .HasValueGenerator<LegacyIdValueGenerator>();
         });

         // Breaking change 3: HasIndex() now throws on the Cosmos
         // provider (it was silently ignored before). Removed.
     }
 }

 class Blog { public string Id { get; set; } public string Name { get; set; } }

 // Generates ids in the legacy "Blog|{guid}" format for backward compat.
 class LegacyIdValueGenerator : Microsoft.EntityFrameworkCore.ValueGeneration.ValueGenerator<string>
 {
     public override bool GeneratesTemporaryValues => false;
     public override string Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
         => $"{entry.Metadata.ShortName()}|{System.Guid.NewGuid()}";
 }
